BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·迎嗣与临朝", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/jiuwudaishi-103-succession-regency/source.txt", "note": "《旧五代史》卷103·隐帝本纪·迎嗣与临朝，段落 jiu-wudaishi-205deb4a7860-p002501；已核上下文及传主，纸本及异文待核。", "id": "50558b51-7a36-5d54-a520-55c401d3f84b"}, {"title": "宋史·卷255·张永德传·受诏拘留", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/songshi-255-zhang-yongde-detained/source.txt", "note": "《宋史》卷255·张永德传·受诏拘留，段落 songshi-9c6e46fee832-p057592；已核上下文及传主，纸本及异文待核。", "id": "480c946c-fbdc-59b5-b8b8-529ba07dfd8c"}, {"title": "宋史·卷255·张永德传·婚姻与押班", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/songshi-255-zhang-yongde-marriage/source.txt", "note": "《宋史》卷255·张永德传·婚姻与押班，段落 songshi-9c6e46fee832-p057591；已核上下文及传主，纸本及异文待核。", "id": "a0cfa87a-ca19-53a4-8dd5-9d137d2685c8"}, {"title": "资治通鉴·卷289·乾祐三年·楚围城前后", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/tongjian-289-950-chu-north-capital/source.txt", "note": "《资治通鉴》卷289·乾祐三年·楚围城前后，段落 zizhi-tongjian-a63549944a71-p003436；已核上下文及传主，纸本及异文待核。", "id": "25894778-12bf-5057-ba19-4a6d3f686baa"}, {"title": "资治通鉴·卷289·乾祐三年·临朝与楚军防御", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/tongjian-289-950-regency-chu-defense/source.txt", "note": "《资治通鉴》卷289·乾祐三年·临朝与楚军防御，段落 zizhi-tongjian-a63549944a71-p003437；已核上下文及传主，纸本及异文待核。", "id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"title": "资治通鉴·卷289·乾祐三年·京师劫掠与禁止", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/31afc3e1ec4e5fd38b43b1838d117faa32a182d4/content/books/zizhi-tongjian/vol-289/year-0950/part-09/sources/library/tongjian-289-950-capital-disorder/source.txt", "note": "《资治通鉴》卷289·乾祐三年·京师劫掠与禁止，段落 zizhi-tongjian-a63549944a71-p003435；已核上下文及传主，纸本及异文待核。", "id": "1b8ccf36-7fc8-5273-974f-40e1c53135eb"}, {"title": "新五代史·卷11·周本纪·郭威南下", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2acb872f407f87ecc1c683ebe4afe35ab5af384e/content/books/zizhi-tongjian/vol-289/year-0950/part-08/sources/library/xinwudaishi-011-guo-march/source.txt", "note": "《新五代史》卷11·周本纪·郭威南下，段落 xin-wudaishi-b08f244b9241-p000366；已核上下文及传主，纸本及异文待核。", "id": "28c8d935-0552-5d17-ac23-4f322402147c"}, {"title": "新五代史·卷66·楚世家·仆射洲之战及后续", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/xinwudaishi-066-pushezhou/source.txt", "note": "《新五代史》卷66·楚世家·仆射洲之战及后续，段落 xin-wudaishi-b08f244b9241-p003329；已核上下文及传主，纸本及异文待核。", "id": "1de76302-3d97-5251-886d-6cba3e293c85"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "刘信（刘知远从弟）", "aliases": ["劉信（劉知遠從弟）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的从弟，后汉将领。947年领义成节度使，兼侍卫马军都指挥使。与先前吴国将领刘信分别建档，生卒年尚未录入。", "biography": null, "status": "draft", "id": "a2f0a9f1-8401-5b6c-9a1e-3a49051af567"}, {"name": "刘赟", "aliases": ["劉赟", "劉贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的儿子，刘知远喜爱他，把他当作自己的儿子。《新五代史》记948年任徐州节度使，949年《通鉴》记以武宁节度使身份获加同平章事。后续经历随主书年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "8b95e2f2-9627-55f8-adca-a0b287179971"}, {"name": "刘承勋", "aliases": ["劉承勛", "劉承勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘承祐的弟弟。950年五月以山南西道节度使身份被任命为开封尹，加兼中书令；《资治通鉴》同时说明他实际尚未出阁。与947年已去世的刘承训分开，生卒年未载。", "biography": null, "status": "draft", "id": "3f17d043-13b1-5bdf-bd39-715c053074f4"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "王度", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉枢密直学士。950年与冯道、赵上交奉郭威奏请之命，到徐州迎接被选为嗣君的刘赟。是否与同名人物有关尚无证据，生卒年未载。", "biography": null, "status": "draft", "id": "4536f603-ebc8-5fc6-8b26-25924874f594"}, {"name": "赵远", "aliases": ["趙遠", "赵上交", "趙上交"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：赵远，六军判官、司谏郎中、谏者。", "biography": null, "status": "draft", "id": "cb4acc0b-f3ec-52fa-9349-c01b93a95023"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "常思", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉昭义节度使。948年讨伐李守贞等三镇时曾驻潼关，后来与郭威、白文珂、刘词分三路进攻河中。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "1d3a1e89-5826-52d4-ba66-55dbc3d91e22"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "朱进忠", "aliases": ["硃进忠", "朱進忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的指挥使。950年率兵三千攻益阳，随后建议马希萼亲自率军攻潭州。电子底本也写硃进忠，统一简体姓名，原文保留。生卒年未载。", "biography": null, "status": "draft", "id": "0ba585e1-d1aa-5ce5-ad37-d02d89127713"}, {"name": "崔洪琏", "aliases": ["崔洪璉", "崔珙璉", "崔珙琏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的牙内指挥使。950年八月条下率七千兵屯玉潭。《新五代史》同职、同兵数、同驻地人物写崔珙璉，保留异字。生卒年未载。", "biography": null, "status": "draft", "id": "779075a2-a9a5-5342-924f-359f8f686d1f"}, {"name": "王赟（楚岳州刺史）", "aliases": ["王赟", "王贇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王环的儿子，楚国岳州刺史。949年受马希广任命为都部署战棹指挥使，在仆射洲击败马希萼，追击时奉马希广命令撤回。生卒年尚未录入。", "biography": null, "status": "draft", "id": "31c5b9cf-6cb4-5f96-a891-18f490536385"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "刘彦瑫", "aliases": ["劉彥瑫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国长直都指挥使。947年与李弘皋等主张拥立马希广，五月乙未称马希范遗命，拥立马希广。生卒年未载。", "biography": null, "status": "draft", "id": "56a833a2-40b7-516a-baac-d3f00b328727"}, {"name": "许可琼", "aliases": ["許可瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "许德勋的儿子，楚国水军指挥使。950年受马希广命率五百艘战舰屯城北津，水军接连南津，由马希崇监军。生卒年未载。", "biography": null, "status": "draft", "id": "31ee592e-a1c4-52e7-8bf7-298a4985dab9"}, {"name": "马希崇", "aliases": ["馬希崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希广的庶弟、马希萼的弟弟。947年任楚天策左司马，秘密致信马希萼指责继位安排，又向他报告马希广的言行并约为内应。生卒年尚未录入。", "biography": null, "status": "draft", "id": "7c876e99-eb52-5864-9569-0ede35f9ff7b"}, {"name": "李彦温", "aliases": ["李彥溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国马军指挥使。950年受马希广命率骑兵屯驼口，控制湘阴道路。生卒年未载。", "biography": null, "status": "draft", "id": "cda9474d-98db-5701-940a-efb99682aaa1"}, {"name": "韩礼", "aliases": ["韓禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国步军指挥使。950年受马希广命率二千人屯杨柳桥，控制栅路。生卒年未载。", "biography": null, "status": "draft", "id": "799d21e2-08dc-5e45-91db-a2e99190ac80"}, {"name": "许德勋", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为楚方统帅。", "biography": null, "status": "draft", "id": "22c59d0c-1661-5bcc-b43e-84d97c1ecda4"}, {"name": "袁嶬", "aliases": ["袁义", "袁義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "袁象先的儿子，950年任左神武统军，受命与刘重进等率禁军在赤冈会师，战败时秘密拜见郭威。通鉴电子本把名写成山义拆字，《新五代史》袁象先传写嶬，《宋史》同次出师写袁义。原字保留，生卒年未载。", "biography": null, "status": "draft", "id": "bba3380d-bf2d-534e-a4c5-c19e9c9d60ca"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "曹威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，950年任邺都行营步军都指挥使。刘承祐密令他与郭崇威杀郭威及监军王峻，本段尚未记实际执行。生卒年未载。", "biography": null, "status": "draft", "id": "c26ccc4f-2658-5be8-b917-885c6c56f287"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "刘铢", "aliases": ["劉銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "陕地人，任河东左都押牙。947年刘知远任命他为河阳节度使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "bcd8da9c-9e21-53c2-a6be-7a6d37b61a32"}, {"name": "李洪建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李业的兄长，950年任侍卫马军都指挥使，后暂判侍卫司相关事务。收到杀王殷家属的命令后，只派人看守并继续供给饮食。生卒年未载。", "biography": null, "status": "draft", "id": "20743d65-b3c4-5fd8-a598-3fa66314e4bc"}, {"name": "后匡赞", "aliases": ["后赞", "後贊", "後匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瑕丘人，后汉飞龙使。949年条下与郭允明一起见于刘承祐近臣的记载。《旧五代史》写后赞，官职及朝廷人物背景相合，本批保留这个异名。生卒年尚未录入。", "biography": null, "status": "draft", "id": "ad25a35f-89f7-538f-8c83-ffe2d366f2ff"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "李业", "aliases": ["李業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，任武德使，刘知远时掌内库，刘承祐即位后受到宠信。950年与刘承祐等策划诛杀杨邠等大臣。出生与死亡年本批未录。", "biography": null, "status": "draft", "id": "0a670b8c-fe4d-5003-96e0-ac1c6b99b1a0"}, {"name": "李洪信", "aliases": ["李洪信（保义节度使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李业的兄长，950年任保义节度使。李业逃到陕州时，他不敢把李业藏在自己家中。生卒年未载。", "biography": null, "status": "draft", "id": "f7765562-57e3-5ab1-943b-817dd4ecb0bf"}, {"name": "田行皋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀施州刺史。946年十一月条下记他叛变，后蜀派供奉官耿彦珣率兵讨伐；原文未给平定结果及生卒年。", "biography": null, "status": "draft", "id": "3e9f4060-5494-5ef9-b6ac-3918c43ce4f8"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
